export const LANGS = ['zh', 'en'];
let lang = localStorage.getItem('lang')
  || (String(navigator.language || '').toLowerCase().startsWith('zh') ? 'zh' : 'en');
if (!LANGS.includes(lang)) lang = 'zh';

const listeners = new Set();

export function getLang() { return lang; }
export function onLangChange(fn) { listeners.add(fn); return () => listeners.delete(fn); }
export function setLang(next) {
  if (!LANGS.includes(next) || next === lang) return;
  lang = next;
  localStorage.setItem('lang', next);
  document.documentElement.lang = next;
  listeners.forEach((fn) => fn(next));
}

export function t(key, vars) {
  const table = DICT[lang] || DICT.zh;
  let s = table[key];
  if (s === undefined) s = DICT.zh[key];
  if (s === undefined) return key; // visible as the raw key -> caught by tools/check-i18n.js
  if (vars) {
    for (const k of Object.keys(vars)) s = s.split('{' + k + '}').join(String(vars[k]));
  }
  return s;
}

export function dictKeys(l) { return Object.keys(DICT[l] || {}); }
document.documentElement.lang = lang;
